fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // The specification requires:
    // res == ( (a as i32 - b as i32) > -(tol as i32) && (a as i32 - b as i32) < (tol as i32) )
    let diff = a as i32 - b as i32;
    diff > -(tol as i32) && diff < (tol as i32)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // The specification requires:
    // For each i, result[i] == (let diff = a[i] as i32 - b[i] as i32; diff > -tol && diff < tol)
    // Also, a.len() == b.len() and tol > 0
    let mut result = Vec::with_capacity(a.len());
    let tol_i32 = tol as i32;
    for i in 0..a.len() {
        let diff = a[i] as i32 - b[i] as i32;
        let close = diff > -tol_i32 && diff < tol_i32;
        result.push(close);
    }
    result
}